Transaction isolation trades consistency for concurrency. Running these scenarios in two MySQL sessions turns the terminology into muscle memory.

```sql
-- Setup (run once)
CREATE TABLE accounts (id INT PRIMARY KEY, balance INT) ENGINE=InnoDB;
INSERT INTO accounts VALUES (1, 1000), (2, 500);

-- =========== READ UNCOMMITTED — dirty reads allowed ===========
-- Session A                              -- Session B
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
BEGIN;                                    BEGIN;
UPDATE accounts SET balance = 0          
  WHERE id = 1;                           SELECT balance FROM accounts WHERE id = 1;
                                          -- returns 0  ← DIRTY READ (A hasn't committed!)
ROLLBACK;                                 -- B saw a value that never officially existed

-- =========== READ COMMITTED — no dirty, but non-repeatable ===========
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- Session A                              -- Session B
BEGIN;                                    BEGIN;
SELECT balance FROM accounts
  WHERE id = 1;  -- 1000                  UPDATE accounts SET balance = 500 WHERE id = 1;
                                          COMMIT;
SELECT balance FROM accounts
  WHERE id = 1;  -- 500  ← NON-REPEATABLE READ
COMMIT;

-- =========== REPEATABLE READ (InnoDB default) — snapshot per transaction ===========
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- Session A                              -- Session B
BEGIN;                                    BEGIN;
SELECT balance FROM accounts
  WHERE id = 1;  -- 1000                  UPDATE accounts SET balance = 500 WHERE id = 1;
                                          COMMIT;
SELECT balance FROM accounts
  WHERE id = 1;  -- STILL 1000  ✓         -- InnoDB uses MVCC snapshot from A's first read
COMMIT;

-- =========== SERIALIZABLE — full isolation via locks ===========
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN;
SELECT SUM(balance) FROM accounts;       -- acquires shared locks on all scanned rows
-- Any concurrent UPDATE in another session blocks until this transaction commits.
COMMIT;
```

| Level | Dirty read | Non-repeatable read | Phantom read | Locking |
| --- | --- | --- | --- | --- |
| `READ UNCOMMITTED` | possible | possible | possible | minimal |
| `READ COMMITTED` | never | possible | possible | short read locks |
| `REPEATABLE READ` | never | never | rare (InnoDB prevents) | gap + next-key |
| `SERIALIZABLE` | never | never | never | shared locks on every read |

- **InnoDB's default is `REPEATABLE READ`** and uses MVCC, so readers do not block writers even at this level — the higher cost you worry about on other databases does not apply.
- `READ COMMITTED` gives higher concurrency and is the right default for most web applications with short transactions and idempotent retries — Oracle and PostgreSQL default here.
- Phantom reads at `REPEATABLE READ` are prevented in InnoDB by **gap locks** and **next-key locks**. This is what lets `SELECT ... FOR UPDATE` reserve ranges.
- `SERIALIZABLE` is safe but slow — every `SELECT` becomes a shared lock. Reserve for true invariant-critical paths (ledger posting) and keep the transaction short.

@Entity
@Table(name = "products")
public class Product {
    @Id @GeneratedValue private Long id;
    private String name;
    private int stockCount;
    private BigDecimal price;

    @Version  // Hibernate auto-increments on every UPDATE
    private Long version;
}

// SQL Hibernate generates on UPDATE:
// UPDATE products
// SET stock_count = ?, price = ?, version = version + 1
// WHERE id = ? AND version = ?     <-- the magic: filter on current version
//
// If another transaction updated the row between your read and write,
// the version no longer matches, the UPDATE affects 0 rows,
// and Hibernate throws OptimisticLockException

@Service
@Transactional
public class ProductService {

    // Retry on conflict with exponential backoff
    @Retryable(
        retryFor = ObjectOptimisticLockingFailureException.class,
        maxAttempts = 3,
        backoff = @Backoff(delay = 50, multiplier = 2.0, random = true)
    )
    public Product updatePrice(Long productId, BigDecimal newPrice) {
        Product p = productRepository.findById(productId)
            .orElseThrow();
        p.setPrice(newPrice);
        return productRepository.save(p);
        // On commit: UPDATE WHERE id=? AND version=?
        // If concurrent update happened, throws OptimisticLockException
        // @Retryable catches it and runs the entire method again
    }
}

// JPA also supports OPTIMISTIC_FORCE_INCREMENT for parent-child consistency:
// when modifying a child, force the parent's version to bump too
// so concurrent edits to siblings still detect the parent change
@Lock(LockModeType.OPTIMISTIC_FORCE_INCREMENT)
Optional<Order> findById(Long id);

// Repository with explicit pessimistic lock
public interface InventoryRepository extends JpaRepository<Inventory, Long> {

    // Generates: SELECT ... FROM inventory WHERE id = ? FOR UPDATE
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT i FROM Inventory i WHERE i.productId = :productId")
    Optional<Inventory> findByProductIdForUpdate(@Param("productId") Long productId);

    // Lock with timeout to avoid indefinite blocking
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @QueryHints({@QueryHint(name = "jakarta.persistence.lock.timeout", value = "5000")})
    @Query("SELECT i FROM Inventory i WHERE i.productId = :productId")
    Optional<Inventory> findByProductIdForUpdateWithTimeout(@Param("productId") Long productId);
}

@Service
@Transactional(timeout = 10) // overall transaction timeout
public class InventoryService {

    public void decrementStock(Long productId, int qty) {
        Inventory inv = inventoryRepository.findByProductIdForUpdate(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));
        // ABOVE: blocks if another transaction holds the lock
        // BELOW: safe to read-modify-write; no other transaction can interfere
        if (inv.getStock() < qty) {
            throw new InsufficientStockException(productId);
        }
        inv.setStock(inv.getStock() - qty);
        // Lock released on commit / rollback
    }
}

// Lock-free alternative for simple counters: atomic UPDATE
// Avoids both optimistic and pessimistic locking entirely
@Modifying
@Query("UPDATE Inventory i SET i.stock = i.stock - :qty " +
       "WHERE i.productId = :pid AND i.stock >= :qty")
int decrementIfAvailable(@Param("pid") Long productId, @Param("qty") int qty);
// Returns 1 if successful, 0 if insufficient stock or row missing
// Database-level atomicity; no application-level locking needed
